import { Session } from '@prisma/client';
import { PrismaService } from '../../../../shared/infrastructure/database/prisma.service';

@Injectable()
export class SessionRepository {
  constructor(private readonly prisma: PrismaService) {}

  async create(data: {
    userId: string;
    refreshTokenHash: string;
    expiresAt: Date;
    ipAddress?: string;
    userAgent?: string;
  }): Promise<Session> {
    return this.prisma.session.create({ data });
  }

  async findByRefreshHash(refreshTokenHash: string): Promise<Session | null> {
    return this.prisma.session.findFirst({
      where: {
        refreshTokenHash,
        revokedAt: null,
        expiresAt: { gt: new Date() },
      },
    });
  }

  async revoke(id: string): Promise<void> {
    await this.prisma.session.update({
      where: { id },
      data: { revokedAt: new Date() },
    });
  }

  async revokeAllForUser(userId: string): Promise<void> {
    await this.prisma.session.updateMany({
      where: { userId, revokedAt: null },
      data: { revokedAt: new Date() },
    });
  }

  async countActiveForUser(userId: string): Promise<number> {
    return this.prisma.session.count({
      where: {
        userId,
        revokedAt: null,
        expiresAt: { gt: new Date() },
      },
    });
  }

  async rotate(id: string, refreshTokenHash: string, expiresAt: Date): Promise<Session> {
    return this.prisma.session.update({
      where: { id },
      data: { refreshTokenHash, expiresAt },
    });
  }
}

import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AUTH_CONFIG_KEY, type AuthConfig } from '../../../../shared/config/app.config';
import { AuditService } from '../../../../shared/infrastructure/audit/audit.service';
import { PrismaService } from '../../../../shared/infrastructure/database/prisma.service';
import { USER_STATUS } from '../../domain/constants/iam.constants';
import {
  AccountBannedException,
  AccountLockedException,
  EmailTakenException,
  InvalidCredentialsException,
  RefreshTokenInvalidException,
  SessionLimitException,
  UserNotFoundException,
  UsernameTakenException,
} from '../../domain/exceptions/iam.exceptions';
import {
  AuthResponseDto,
  LoginDto,
  RegisterDto,
  UpdateProfileDto,
  UserProfileDto,
} from '../dto/auth.dto';
import { PasswordHasherService } from './password-hasher.service';
import { TokenService } from './token.service';
import { SessionRepository } from '../../infrastructure/repositories/session.repository';
import { UserRepository, UserWithRoles } from '../../infrastructure/repositories/user.repository';

type RequestMeta = {
  ipAddress?: string;
  userAgent?: string;
  correlationId?: string;
};

@Injectable()
export class AuthApplicationService {
  private readonly lockouts = new Map<string, { count: number; lockedUntil?: number }>();

  constructor(
    private readonly userRepository: UserRepository,
    private readonly sessionRepository: SessionRepository,
    private readonly passwordHasher: PasswordHasherService,
    private readonly tokenService: TokenService,
    private readonly auditService: AuditService,
    private readonly prisma: PrismaService,
    private readonly configService: ConfigService,
  ) {}

  async register(dto: RegisterDto, meta: RequestMeta): Promise<AuthResponseDto> {
    if (!dto.acceptTerms) {
      throw new HttpException(
        { code: 'TERMS_NOT_ACCEPTED', message: 'You must accept terms' },
        HttpStatus.UNPROCESSABLE_ENTITY,
      );
    }

    const email = dto.email.toLowerCase();
    const username = dto.username.toLowerCase();

    if (await this.userRepository.findByEmail(email)) {
      throw new EmailTakenException();
    }
    if (await this.userRepository.findByUsername(username)) {
      throw new UsernameTakenException();
    }

    this.passwordHasher.validatePolicy(dto.password, username);
    const passwordHash = await this.passwordHasher.hash(dto.password);

    const user = await this.prisma.$transaction(async (tx) => {
      const role = await tx.role.findUnique({ where: { name: 'user' } });
      if (!role) {
        throw new Error('Default role "user" not found. Run db:seed first.');
      }

      const created = await tx.user.create({
        data: {
          email,
          username,
          displayName: dto.displayName,
          passwordHash,
          userRoles: { create: { roleId: role.id } },
        },
      });

      await tx.account.create({
        data: {
          ownerId: created.id,
          ownerType: 'USER',
          accountType: 'MAIN',
        },
      });

      return created;
    });

    await this.auditService.log({
      actorId: user.id,
      action: 'user.register',
      resourceType: 'user',
      resourceId: user.id,
      newValues: { email: user.email, username: user.username },
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      correlationId: meta.correlationId,
    });

    return this.createSessionForUser(user.id, meta);
  }

  async login(dto: LoginDto, meta: RequestMeta): Promise<AuthResponseDto> {
    const email = dto.email.toLowerCase();
    this.ensureNotLocked(email);

    const user = await this.userRepository.findByEmail(email);
    if (!user) {
      this.recordFailedAttempt(email);
      throw new InvalidCredentialsException();
    }

    if (user.status === USER_STATUS.BANNED) {
      throw new AccountBannedException();
    }

    const valid = await this.passwordHasher.verify(user.passwordHash, dto.password);
    if (!valid) {
      this.recordFailedAttempt(email);
      throw new InvalidCredentialsException();
    }

    this.clearFailedAttempts(email);

    await this.auditService.log({
      actorId: user.id,
      action: 'user.login',
      resourceType: 'user',
      resourceId: user.id,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      correlationId: meta.correlationId,
    });

    return this.createSessionForUser(user.id, meta);
  }

  async refresh(refreshToken: string, meta: RequestMeta): Promise<AuthResponseDto> {
    const hash = this.tokenService.hashRefreshToken(refreshToken);
    const session = await this.sessionRepository.findByRefreshHash(hash);
    if (!session) {
      throw new RefreshTokenInvalidException();
    }

    const user = await this.userRepository.findById(session.userId);
    if (!user || user.status === USER_STATUS.BANNED) {
      throw new RefreshTokenInvalidException();
    }

    const newRefreshToken = this.tokenService.generateRefreshToken();
    const newHash = this.tokenService.hashRefreshToken(newRefreshToken);
    await this.sessionRepository.rotate(session.id, newHash, this.tokenService.getRefreshExpiresAt());

    const response = this.buildAuthResponse(user);
    return { ...response, refreshToken: newRefreshToken } as AuthResponseDto & { refreshToken: string };
  }

  async logout(refreshToken: string | undefined, userId: string | undefined, meta: RequestMeta): Promise<void> {
    if (refreshToken) {
      const hash = this.tokenService.hashRefreshToken(refreshToken);
      const session = await this.sessionRepository.findByRefreshHash(hash);
      if (session) {
        await this.sessionRepository.revoke(session.id);
      }
    }

    if (userId) {
      await this.auditService.log({
        actorId: userId,
        action: 'user.logout',
        resourceType: 'user',
        resourceId: userId,
        ipAddress: meta.ipAddress,
        userAgent: meta.userAgent,
        correlationId: meta.correlationId,
      });
    }
  }

  async getProfile(userId: string): Promise<UserProfileDto> {
    const user = await this.userRepository.findById(userId);
    if (!user) {
      throw new UserNotFoundException();
    }
    return this.toProfileDto(user);
  }

  async updateProfile(userId: string, dto: UpdateProfileDto, meta: RequestMeta): Promise<UserProfileDto> {
    const user = await this.userRepository.findById(userId);
    if (!user) {
      throw new UserNotFoundException();
    }

    const updated = await this.userRepository.update(userId, {
      displayName: dto.displayName,
      bio: dto.bio,
      city: dto.city,
    });

    await this.auditService.log({
      actorId: userId,
      action: 'user.update_profile',
      resourceType: 'user',
      resourceId: userId,
      oldValues: { displayName: user.displayName, bio: user.bio, city: user.city },
      newValues: { displayName: updated.displayName, bio: updated.bio, city: updated.city },
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      correlationId: meta.correlationId,
    });

    const refreshed = await this.userRepository.findById(userId);
    if (!refreshed) {
      throw new UserNotFoundException();
    }
    return this.toProfileDto(refreshed);
  }

  private async createSessionForUser(userId: string, meta: RequestMeta): Promise<AuthResponseDto & { refreshToken: string }> {
    const authConfig = this.configService.get<AuthConfig>(AUTH_CONFIG_KEY);
    const maxSessions = authConfig?.maxSessionsPerUser ?? 5;
    const activeSessions = await this.sessionRepository.countActiveForUser(userId);
    if (activeSessions >= maxSessions) {
      throw new SessionLimitException();
    }

    const user = await this.userRepository.findById(userId);
    if (!user) {
      throw new UserNotFoundException();
    }

    const refreshToken = this.tokenService.generateRefreshToken();
    await this.sessionRepository.create({
      userId,
      refreshTokenHash: this.tokenService.hashRefreshToken(refreshToken),
      expiresAt: this.tokenService.getRefreshExpiresAt(),
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
    });

    await this.userRepository.update(userId, { lastActiveAt: new Date() });

    return {
      ...this.buildAuthResponse(user),
      refreshToken,
    };
  }

  private buildAuthResponse(user: UserWithRoles): AuthResponseDto {
    const roles = this.userRepository.extractRoles(user);
    const permissions = this.userRepository.extractPermissions(user);
    const accessToken = this.tokenService.generateAccessToken({
      sub: user.id,
      email: user.email,
      username: user.username,
      roles,
      permissions,
    });

    return {
      user: {
        id: user.id,
        email: user.email,
        username: user.username,
        displayName: user.displayName,
        emailVerified: user.emailVerified,
        roles,
      },
      accessToken,
      expiresIn: this.tokenService.getAccessExpiresIn(),
    };
  }

  private toProfileDto(user: UserWithRoles): UserProfileDto {
    return {
      id: user.id,
      email: user.email,
      username: user.username,
      displayName: user.displayName,
      emailVerified: user.emailVerified,
      roles: this.userRepository.extractRoles(user),
      bio: user.bio,
      city: user.city,
      country: user.country,
      level: user.level,
      experiencePoints: user.experiencePoints,
      createdAt: user.createdAt.toISOString(),
    };
  }

  private ensureNotLocked(email: string): void {
    const authConfig = this.configService.get<AuthConfig>(AUTH_CONFIG_KEY);
    const entry = this.lockouts.get(email);
    if (entry?.lockedUntil && entry.lockedUntil > Date.now()) {
      throw new AccountLockedException();
    }
    if (entry?.lockedUntil && entry.lockedUntil <= Date.now()) {
      this.lockouts.delete(email);
    }
    void authConfig;
  }

  private recordFailedAttempt(email: string): void {
    const authConfig = this.configService.get<AuthConfig>(AUTH_CONFIG_KEY);
    const maxAttempts = authConfig?.maxFailedAttempts ?? 5;
    const lockoutDurationMs = authConfig?.lockoutDurationMs ?? 15 * 60 * 1000;

    const entry = this.lockouts.get(email) ?? { count: 0 };
    entry.count += 1;
    if (entry.count >= maxAttempts) {
      entry.lockedUntil = Date.now() + lockoutDurationMs;
    }
    this.lockouts.set(email, entry);
  }

  private clearFailedAttempts(email: string): void {
    this.lockouts.delete(email);
  }
}

import { createParamDecorator, ExecutionContext, SetMetadata } from '@nestjs/common';
import { Request } from 'express';
import type { AccessTokenPayload } from '../../application/services/token.service';

export const IS_PUBLIC_KEY = 'isPublic';
export const Public = (): ReturnType<typeof SetMetadata> => SetMetadata(IS_PUBLIC_KEY, true);

export const PERMISSIONS_KEY = 'permissions';
export const RequirePermission = (...permissions: string[]): ReturnType<typeof SetMetadata> =>
  SetMetadata(PERMISSIONS_KEY, permissions);

export type AuthUser = AccessTokenPayload;

export const CurrentUser = createParamDecorator((_data: unknown, ctx: ExecutionContext): AuthUser => {
  const request = ctx.switchToHttp().getRequest<Request & { user: AuthUser }>();
  return request.user;
});

export type RequestWithMeta = Request & {
  user?: AuthUser;
  correlationId?: string;
};

export function getRequestMeta(req: RequestWithMeta): {
  ipAddress?: string;
  userAgent?: string;
  correlationId?: string;
} {
  return {
    ipAddress: req.ip,
    userAgent: req.headers['user-agent'],
    correlationId: req.correlationId,
  };
}

import { ExecutionContext, Injectable, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { AuthGuard } from '@nestjs/passport';
import { IS_PUBLIC_KEY } from '../decorators/auth.decorators';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  constructor(private readonly reflector: Reflector) {
    super();
  }

  canActivate(context: ExecutionContext) {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) {
      return true;
    }
    return super.canActivate(context);
  }

  handleRequest<TUser>(err: Error | null, user: TUser): TUser {
    if (err || !user) {
      throw err ?? new UnauthorizedException('Invalid or expired token');
    }
    return user;
  }
}

import { CanActivate, ExecutionContext, ForbiddenException, Injectable } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PERMISSIONS_KEY, type AuthUser } from '../decorators/auth.decorators';

@Injectable()
export class PermissionGuard implements CanActivate {
  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const required = this.reflector.getAllAndOverride<string[]>(PERMISSIONS_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (!required || required.length === 0) {
      return true;
    }

    const request = context.switchToHttp().getRequest<{ user?: AuthUser }>();
    const user = request.user;
    if (!user) {
      throw new ForbiddenException('Authentication required');
    }

    const hasPermission = required.some((p) => user.permissions.includes(p));
    if (!hasPermission) {
      throw new ForbiddenException(`Missing permission: ${required.join(' or ')}`);
    }
    return true;
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { JWT_CONFIG_KEY, type JwtConfig } from '../../../../shared/config/app.config';
import type { AccessTokenPayload } from '../../application/services/token.service';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(configService: ConfigService) {
    const jwtConfig = configService.get<JwtConfig>(JWT_CONFIG_KEY);
    if (!jwtConfig?.secret) {
      throw new Error('JWT configuration is missing');
    }
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: jwtConfig.secret,
    });
  }

  validate(payload: AccessTokenPayload): AccessTokenPayload {
    if (!payload.sub) {
      throw new UnauthorizedException();
    }
    return payload;
  }
}

import { Body, Controller, Get, Patch, Post, Req, Res } from '@nestjs/common';
import { ApiBearerAuth, ApiOperation, ApiTags } from '@nestjs/swagger';
import { Response } from 'express';
import { AuthApplicationService } from '../../application/services/auth-application.service';
import { LoginDto, RegisterDto, UpdateProfileDto } from '../../application/dto/auth.dto';
import { TokenService } from '../../application/services/token.service';
import {
  CurrentUser,
  getRequestMeta,
  Public,
  type AuthUser,
  type RequestWithMeta,
} from '../decorators/auth.decorators';

@ApiTags('auth')
@Controller('auth')
export class AuthController {
  constructor(
    private readonly authService: AuthApplicationService,
    private readonly tokenService: TokenService,
  ) {}

  @Public()
  @Post('register')
  @ApiOperation({ summary: 'Register new user' })
  async register(
    @Body() dto: RegisterDto,
    @Req() req: RequestWithMeta,
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.authService.register(dto, getRequestMeta(req));
    this.setRefreshCookie(res, result.refreshToken);
    const { refreshToken: _, ...data } = result;
    return { data };
  }

  @Public()
  @Post('login')
  @ApiOperation({ summary: 'Login' })
  async login(
    @Body() dto: LoginDto,
    @Req() req: RequestWithMeta,
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.authService.login(dto, getRequestMeta(req));
    this.setRefreshCookie(res, result.refreshToken);
    const { refreshToken: _, ...data } = result;
    return { data };
  }

  @Public()
  @Post('refresh')
  @ApiOperation({ summary: 'Refresh access token' })
  async refresh(
    @Req() req: RequestWithMeta,
    @Res({ passthrough: true }) res: Response,
  ) {
    const cookieName = this.tokenService.getRefreshCookieName();
    const refreshToken = req.cookies?.[cookieName] as string | undefined;
    if (!refreshToken) {
      return res.status(401).json({
        type: 'https://api.luchi.app/errors/refresh-token-expired',
        title: 'Unauthorized',
        status: 401,
        detail: 'Refresh token missing',
        code: 'REFRESH_TOKEN_EXPIRED',
      });
    }
    const result = await this.authService.refresh(refreshToken, getRequestMeta(req));
    this.setRefreshCookie(res, result.refreshToken);
    const { refreshToken: _, ...data } = result;
    return { data };
  }

  @Post('logout')
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Logout' })
  async logout(
    @CurrentUser() user: AuthUser,
    @Req() req: RequestWithMeta,
    @Res({ passthrough: true }) res: Response,
  ) {
    const cookieName = this.tokenService.getRefreshCookieName();
    const refreshToken = req.cookies?.[cookieName] as string | undefined;
    await this.authService.logout(refreshToken, user.sub, getRequestMeta(req));
    res.clearCookie(cookieName, { path: '/api/v1/auth' });
    return { data: { success: true } };
  }

  private setRefreshCookie(res: Response, refreshToken: string): void {
    const cookieName = this.tokenService.getRefreshCookieName();
    const isProduction = process.env.NODE_ENV === 'production';
    res.cookie(cookieName, refreshToken, {
      httpOnly: true,
      secure: isProduction,
      sameSite: 'strict',
      path: '/api/v1/auth',
      maxAge: this.tokenService.getRefreshCookieMaxAge(),
    });
  }
}

@ApiTags('users')
@ApiBearerAuth()
@Controller('users')
export class UsersController {
  constructor(private readonly authService: AuthApplicationService) {}

  @Get('me')
  @ApiOperation({ summary: 'Get current user profile' })
  async getMe(@CurrentUser() user: AuthUser, @Req() req: RequestWithMeta) {
    void req;
    const profile = await this.authService.getProfile(user.sub);
    return { data: profile };
  }

  @Patch('me')
  @ApiOperation({ summary: 'Update current user profile' })
  async updateMe(
    @CurrentUser() user: AuthUser,
    @Body() dto: UpdateProfileDto,
    @Req() req: RequestWithMeta,
  ) {
    const profile = await this.authService.updateProfile(user.sub, dto, getRequestMeta(req));
    return { data: profile };
  }
}

import { Module } from '@nestjs/common';
import { APP_GUARD } from '@nestjs/core';
import { JwtModule } from '@nestjs/jwt';
import { PassportModule } from '@nestjs/passport';
import { ConfigModule, ConfigService } from '@nestjs/config';
import { JWT_CONFIG_KEY, type JwtConfig } from '../../shared/config/app.config';
import { AuthApplicationService } from './application/services/auth-application.service';
import { PasswordHasherService } from './application/services/password-hasher.service';
import { TokenService } from './application/services/token.service';
import { SessionRepository } from './infrastructure/repositories/session.repository';
import { UserRepository } from './infrastructure/repositories/user.repository';
import { JwtStrategy } from './infrastructure/strategies/jwt.strategy';
import { AuthController, UsersController } from './presentation/controllers/auth.controller';
import { JwtAuthGuard } from './presentation/guards/jwt-auth.guard';
import { PermissionGuard } from './presentation/guards/permission.guard';

@Module({
  imports: [
    PassportModule.register({ defaultStrategy: 'jwt' }),
    JwtModule.registerAsync({
      imports: [ConfigModule],
      inject: [ConfigService],
      useFactory: (configService: ConfigService) => {
        const jwtConfig = configService.get<JwtConfig>(JWT_CONFIG_KEY);
        if (!jwtConfig?.secret) {
          throw new Error('JWT configuration is missing');
        }
        return {
          secret: jwtConfig.secret,
          signOptions: { expiresIn: jwtConfig.accessTtl },
        };
      },
    }),
  ],
  controllers: [AuthController, UsersController],
  providers: [
    AuthApplicationService,
    PasswordHasherService,
    TokenService,
    UserRepository,
    SessionRepository,
    JwtStrategy,
    { provide: APP_GUARD, useClass: JwtAuthGuard },
    { provide: APP_GUARD, useClass: PermissionGuard },
  ],
  exports: [AuthApplicationService, UserRepository, TokenService],
})
export class IamModule {}

