'use client';

import { Button } from '@luchi/ui';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { FormEvent, useState } from 'react';

const API_URL = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:3001/api/v1';

export default function LoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState('demo@luchi.app');
  const [password, setPassword] = useState('DemoP@ss123!');
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  async function handleSubmit(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`${API_URL}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ email, password }),
      });
      const body = await response.json();
      if (!response.ok) {
        setError(body.detail ?? 'Ошибка входа');
        return;
      }
      localStorage.setItem('access_token', body.data.accessToken);
      router.push('/profile');
    } catch {
      setError('API недоступен. Запустите docker compose и npm run dev');
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="flex min-h-screen items-center justify-center px-4">
      <div className="w-full max-w-md rounded-2xl bg-white p-8 shadow-sm">
        <div className="mb-6 text-center">
          <span className="text-3xl" aria-hidden="true">
            ☀
          </span>
          <h1 className="mt-2 text-2xl font-bold">Вход в ЛУЧИ</h1>
        </div>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="mb-1 block text-sm font-medium" htmlFor="email">
              Email
            </label>
            <input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full rounded-lg border border-gray-100 px-3 py-2"
              required
            />
          </div>
          <div>
            <label className="mb-1 block text-sm font-medium" htmlFor="password">
              Пароль
            </label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full rounded-lg border border-gray-100 px-3 py-2"
              required
            />
          </div>
          {error && <p className="text-sm text-red-500">{error}</p>}
          <Button variant="rays" size="lg" className="w-full" disabled={loading}>
            {loading ? 'Вход...' : 'Войти'}
          </Button>
        </form>
        <p className="mt-4 text-center text-sm text-gray-900/60">
          Нет аккаунта?{' '}
          <Link href="/register" className="text-sky underline">
            Регистрация
          </Link>
        </p>
      </div>
    </main>
  );
}

'use client';

import { Button, RayBalance } from '@luchi/ui';
import Link from 'next/link';
import { FormEvent, useState } from 'react';

const API_URL = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:3001/api/v1';

export default function RegisterPage() {
  const [form, setForm] = useState({
    email: '',
    username: '',
    displayName: '',
    password: 'DemoP@ss123!',
    acceptTerms: true,
  });
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  async function handleSubmit(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault();
    setLoading(true);
    setError(null);
    setMessage(null);

    try {
      const response = await fetch(`${API_URL}/auth/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(form),
      });
      const body = await response.json();
      if (!response.ok) {
        setError(body.detail ?? 'Ошибка регистрации');
        return;
      }
      localStorage.setItem('access_token', body.data.accessToken);
      setMessage(`Добро пожаловать, ${body.data.user.displayName}!`);
    } catch {
      setError('API недоступен');
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="flex min-h-screen items-center justify-center px-4 py-8">
      <div className="w-full max-w-md rounded-2xl bg-white p-8 shadow-sm">
        <h1 className="mb-6 text-2xl font-bold">Регистрация</h1>
        <form onSubmit={handleSubmit} className="space-y-3">
          {(['email', 'username', 'displayName', 'password'] as const).map((field) => (
            <div key={field}>
              <label className="mb-1 block text-sm capitalize" htmlFor={field}>
                {field === 'displayName' ? 'Имя' : field}
              </label>
              <input
                id={field}
                type={field === 'password' ? 'password' : 'text'}
                value={form[field]}
                onChange={(e) => setForm({ ...form, [field]: e.target.value })}
                className="w-full rounded-lg border border-gray-100 px-3 py-2"
                required
              />
            </div>
          ))}
          {error && <p className="text-sm text-red-500">{error}</p>}
          {message && (
            <p className="text-sm text-green-600">
              {message} <RayBalance balance={0} size="sm" />
            </p>
          )}
          <Button variant="rays" className="w-full" disabled={loading}>
            {loading ? 'Создание...' : 'Создать аккаунт'}
          </Button>
        </form>
        <p className="mt-4 text-center text-sm">
          <Link href="/login" className="text-sky underline">
            Уже есть аккаунт
          </Link>
        </p>
      </div>
    </main>
  );
}

'use client';

import { RayBalance } from '@luchi/ui';
import Link from 'next/link';
import { useEffect, useState } from 'react';

const API_URL = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:3001/api/v1';

type Profile = {
  displayName: string;
  username: string;
  email: string;
  level: number;
  roles: string[];
};

export default function ProfilePage() {
  const [profile, setProfile] = useState<Profile | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const token = localStorage.getItem('access_token');
    if (!token) {
      setError('Не авторизован');
      return;
    }
    fetch(`${API_URL}/users/me`, {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then(async (res) => {
        const body = await res.json();
        if (!res.ok) {
          throw new Error(body.detail ?? 'Ошибка');
        }
        setProfile(body.data);
      })
      .catch((err: Error) => setError(err.message));
  }, []);

  return (
    <main className="mx-auto max-w-lg px-6 py-16">
      <Link href="/" className="text-sky underline">
        ← На главную
      </Link>
      <div className="mt-6 rounded-2xl bg-white p-8 shadow-sm">
        {error && <p className="text-red-500">{error}</p>}
        {profile && (
          <>
            <h1 className="text-2xl font-bold">{profile.displayName}</h1>
            <p className="text-gray-900/60">@{profile.username}</p>
            <p className="mt-2">{profile.email}</p>
            <div className="mt-4 flex items-center gap-4">
              <RayBalance balance={0} size="lg" />
              <span>Уровень {profile.level}</span>
            </div>
            <p className="mt-2 text-sm text-gray-900/60">Роли: {profile.roles.join(', ')}</p>
          </>
        )}
      </div>
    </main>
  );
}

